public void setProperty(String property, boolean v) {
  try {
    this.setProperty(property, v ? String.valueOf(true) : String.valueOf(false));
  } catch (NullPointerException e) {
    // Handle the exception, possibly logging or re-throwing
    System.out.println("Property name cannot be null");
  } catch (RuntimeException e) {
    // Handle any other runtime exceptions
    System.out.println("An unexpected error occurred: " + e.getMessage());
  }
}
